select kind in ('a', 'b') as listed, kind not in ('a') as unlisted, kind in ('a', null) as with_null, note in ('a') as of_null, amount between 1 and 2 as between, amount not between symmetric 2 and 1 as outside, id = any (array[1, 2]) as any_listed, id <> all (array[1, 2]) as all_listed, id = any (array[1, null]) as any_null, kind = any (tags) as any_column, kind is json as json, note is json as note_json from events
